function icrStableCreate(array$state,string$table):string{return preg_replace('/ AUTO_INCREMENT=\d+/','',(string)($state[$table]['create'][1]??''))??'';}
function icrPort():int{$s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if(!$s)throw new TestFailure('SETUP_FAILURE: port');$n=(string)stream_socket_get_name($s,false);fclose($s);return(int)substr($n,strrpos($n,':')+1);}
function icrStart(array$env):array{$port=icrPort();$r=proc_open([PHP_BINARY,'-d','expose_php=0','-S','127.0.0.1:'.$port,dirname(__DIR__).'/Support/installation_completion_runtime_router.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),$env);if(!is_resource($r))throw new TestFailure('SETUP_FAILURE: HTTP start');fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$end=microtime(true)+5;do{$s=@stream_socket_client('tcp://127.0.0.1:'.$port,$e,$m,.1);if($s){fclose($s);return compact('port','r','pipes');}usleep(20000);}while(microtime(true)<$end);throw new TestFailure('SETUP_FAILURE: HTTP listen');}
function icrStop(array$s):void{proc_terminate($s['r']);foreach([1,2]as$i){stream_get_contents($s['pipes'][$i]);fclose($s['pipes'][$i]);}proc_close($s['r']);}
/** @return array{status:int,headers:array<string,list<string>>,body:string} */
function icrHttp(int$p,string$m,string$path,string$body=''):array{$s=stream_socket_client('tcp://127.0.0.1:'.$p,$e,$x,5);if(!$s)throw new TestFailure('SETUP_FAILURE: connect');fwrite($s,"$m $path HTTP/1.1\r\nHost: completion.example\r\nConnection: close\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: ".strlen($body)."\r\n\r\n$body");stream_socket_shutdown($s,STREAM_SHUT_WR);$raw='';while(!feof($s))$raw.=(string)fread($s,65536);fclose($s);[$h,$b]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$lines=explode("\r\n",$h);preg_match('/^HTTP\/\d\.\d (\d{3})/',(string)array_shift($lines),$x);$headers=[];foreach($lines as$l)if(str_contains($l,':')){[$k,$v]=explode(':',$l,2);$headers[strtolower(trim($k))][]=trim($v);}return['status'=>(int)($x[1]??0),'headers'=>$headers,'body'=>$b];}
function icrUnavailable(array$r,string$type,bool$head=false,?int$getLength=null):void{assertSameValue(503,$r['status'],"$type 503");assertSameValue(['text/plain; charset=UTF-8'],$r['headers']['content-type']??[],"$type content type");assertSameValue(['no-store'],$r['headers']['cache-control']??[],"$type exact no-store");assertSameValue(false,isset($r['headers']['location']),"$type no redirect");if($type==='queue')assertSameValue(1,preg_match('/\\AService unavailable\\. Reference: [0-9a-f]{12}\\n\\z/D',$r['body']),'queue opaque reference');else{assertSameValue(['60'],$r['headers']['retry-after']??[],"$type Retry-After");if(!$head)assertSameValue("Service unavailable.\n",$r['body'],"$type exact body");else{assertSameValue('',$r['body'],"$type HEAD body empty");assertSameValue([(string)$getLength],$r['headers']['content-length']??[],"$type HEAD declared length equals GET bytes");}}}
function icrRemove(string$p):void{if(!is_dir($p))return;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($p,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as$f)$f->isDir()?@rmdir($f->getPathname()):@unlink($f->getPathname());@rmdir($p);}
