}
function icrVerifyOtizDriftSensitivity(mysqli$db):void
{
    foreach(['missing_table_'=>'DROP TABLE %s','missing_unique_'=>'ALTER TABLE %s DROP KEY unique_reversal']as$p=>$sql){
        icrSeedBootstrapSchemas($db,$p);
        \FMonitor2\InstallationProcess\MariaDbPilotLegacyObjectSchemaReadiness::assertOtizReady($db,$p);
        $target=$p.($p==='missing_table_'?'fm2_pilot_otiz_events':'fm2_pilot_otiz_payment_closures');
        $db->query(sprintf($sql,icrQ($target)));$rejected=false;
        try{\FMonitor2\InstallationProcess\MariaDbPilotLegacyObjectSchemaReadiness::assertOtizReady($db,$p);}catch(\FMonitor2\InstallationProcess\DatabaseUnavailable){$rejected=true;}
        assertSameValue(true,$rejected,"test-owned OTIZ $p drift is rejected read-only");icrDropPrefix($db,$p);
    }
}

